messages.content:
: factorial  ( n -- n! )
  dup 1 <= if drop 1 exit then
  dup 1- recurse * ;

: cell-array  ( n "name" -- )
  create cells allot
  does>     ( i a-addr -- addr )  swap cells + ;

: clamp  ( n lo hi -- n' )
  { n lo hi }
  n hi min  lo max ;

: gcd  ( a b -- g )
  { a b }
  begin b while
    b a b mod  to b  to a
  repeat
  a ;
